<div class="card mb-3"><div class="card-header"><h3 class="card-title">Capaian per <?= html_escape($config['unit']); ?></h3></div><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th><?= html_escape($config['unit']); ?></th><th>Aktivitas</th><th><?= $unitLabels[0]; ?></th><th><?= $unitLabels[1]; ?></th><th><?= $unitLabels[2]; ?></th><th>Terakhir</th><th></th></tr></thead><tbody><?php foreach($data['units'] as $x): ?><tr><td><strong><?= html_escape($x['title']); ?></strong></td><td><?= (int)$x['records']; ?></td><td><?= html_escape((string)$x['success']); ?></td><td><?= html_escape((string)$x['activity']); ?></td><td><?= html_escape((string)$x['total']); ?></td><td><?= $x['last_at']?html_escape(date('d M Y H:i',strtotime($x['last_at']))):'—'; ?></td><td><?php if((int)$x['id']>0): ?><button class="btn btn-outline-danger btn-sm js-reset" data-action="<?= base_url($config['base'].'/progress/user/'.$u['id'].'/reset/'.$x['id']); ?>" data-title="<?= html_escape($config['unit'].' — '.$x['title']); ?>" data-detail="Hanya progres <?= strtolower(html_escape($config['unit'])); ?> ini yang dihapus; riwayat lainnya tetap aman."><i class="ti ti-refresh"></i> Reset <?= html_escape($config['unit']); ?></button><?php else: ?><span class="text-secondary">Reset lewat seluruh progres</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card"><div class="card-header"><h3 class="card-title">Riwayat Aktivitas</h3><span class="badge bg-blue-lt ms-auto"><?= count($data['history']); ?> rekaman terbaru</span></div><div class="table-responsive" style="max-height:560px"><table class="table table-sm card-table"><thead><tr><th>Waktu</th><th><?= html_escape($config['unit']); ?></th><th>Rincian</th><th>Hasil</th><th>Status</th><?php if($module==='battle'): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($data['history'] as $h): ?><tr><td><?= html_escape(date('d M Y H:i',strtotime($h['last_reviewed_at']??$h['created_at']??$h['played_at']??$h['joined_at']))); ?></td><td><strong><?= html_escape($h['unit_title']?:'Battle Bebas'); ?></strong></td><td><?php if($module==='flashcard'): ?><?= html_escape($h['detail']); ?> · <?= (int)$h['review_count']; ?> review<?php elseif($module==='story'): ?><?= (int)$h['correct_count']; ?>/<?= (int)$h['total_questions']; ?> benar · <?= gmdate('i:s',(int)$h['duration_seconds']); ?><?php elseif($module==='mini_games'): ?><?= (int)$h['score']; ?>/<?= (int)$h['max_score']; ?> · <?= gmdate('i:s',(int)$h['duration_seconds']); ?><?php elseif($module==='english_course'): ?><?= html_escape($h['detail']); ?><?php else: ?>Room <code><?= html_escape($h['room_code']); ?></code> · <?= ($h['play_mode']??'sprint')==='paced'?'Per soal':'Sprint'; ?> · progres <?= (int)$h['progress']; ?>/<?= (int)$h['question_count']; ?><?php endif; ?></td><td><?php if($module==='flashcard'): ?><?= $h['status']==='known'?'Dikuasai':'Dipelajari'; ?><?php elseif($module==='story'): ?><?= html_escape($h['score_percent']); ?>%<?php elseif($module==='mini_games'): ?>Skor <?= (int)$h['score']; ?><?php elseif($module==='english_course'): ?>Skor <?= (int)$h['score']; ?><?php else: ?><b>#<?= (int)$h['rank']; ?>/<?= (int)$h['participant_count']; ?></b> · Skor <?= number_format((int)$h['score'],0,',','.'); ?> <?= (int)$h['winner_participant_id']===(int)$h['id']||($h['winner_participant_id']===null&&(int)$h['winner_user_id']===(int)$u['id'])?'· Juara':''; ?><?php endif; ?></td><td><span class="badge bg-<?= (($h['completed']??$h['finished']??0)||($h['status']??'')==='known')?'success':'blue'; ?>-lt"><?= (($h['completed']??$h['finished']??0)||($h['status']??'')==='known')?'Selesai':'Berjalan'; ?></span></td><?php if($module==='battle'): ?><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('learn-battle/progress/run/'.$h['room_id']); ?>">Lihat Lomba</a></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="modal modal-blur fade" id="moduleResetModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content overflow-hidden border-0 shadow-lg"><div class="p-4 text-white" style="background:linear-gradient(135deg,#f97316,#dc2626)"><div class="d-flex align-items-center"><span class="avatar avatar-lg bg-white text-danger rounded-circle me-3"><i class="ti ti-alert-triangle fs-1"></i></span><div><div class="small text-uppercase opacity-75 fw-bold">Konfirmasi reset progres</div><h2 class="text-white mb-0" id="resetTitle"></h2></div><button class="btn-close btn-close-white ms-auto" data-bs-dismiss="modal"></button></div></div><div class="modal-body p-4"><p class="fs-3" id="resetDetail"></p><div class="alert alert-danger mb-0"><i class="ti ti-alert-circle me-1"></i> Tindakan ini permanen dan tidak dapat dibatalkan.</div></div><div class="modal-footer bg-light"><button class="btn btn-link link-secondary" data-bs-dismiss="modal">Batal, simpan progres</button><?= form_open('', ['id'=>'moduleResetForm']); ?><button class="btn btn-danger" id="doReset"><i class="ti ti-trash"></i> Ya, reset progres</button><?= form_close(); ?></div></div></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){var el=document.getElementById('moduleResetModal'),modal=bootstrap.Modal.getOrCreateInstance(el),form=document.getElementById('moduleResetForm');document.querySelectorAll('.js-reset').forEach(function(b){b.addEventListener('click',function(){form.action=b.dataset.action;document.getElementById('resetTitle').textContent=b.dataset.title;document.getElementById('resetDetail').textContent=b.dataset.detail;modal.show();});});form.addEventListener('submit',function(){var b=document.getElementById('doReset');b.disabled=true;b.innerHTML='<span class="spinner-border spinner-border-sm me-2"></span>Mereset...';});});</script>
